SELECT SVC_NUM, USER_ID, TYPE_LVL2_NAME,SVC_NUM AS ENCRYPTED_SVC_NUM
    FROM ZQZT_CUST_MAINT_INFO a
WHERE a.STATUS = '1'
  AND (
    a.CUST_GRP_ID = #{hqGrpCode}
   OR EXISTS (
    SELECT 1 FROM TF_F_CUST_GROUP_M b
    WHERE b.CUST_ID = a.CUST_ID
  AND b.GROUP_ID = #{hqGrpCode}
    )
    )
  AND NOT EXISTS (
    SELECT 1 FROM ZQZT_GRP_CONTRACT_OTHER_INFO c
    WHERE c.INFO_VAL = a.USER_ID
  AND c.CONTRACT_ID = #{contractId}
  AND c.INFO_TAG = 'GRP_CONTRACT_USER_LIST'
  AND c.IS_VALID = 1
    )

SELECT SVC_NUM, USER_ID, TYPE_LVL2_NAME,SVC_NUM AS ENCRYPTED_SVC_NUM
FROM ZQZT_CUST_MAINT_INFO
WHERE STATUS = '1'
AND (
CUST_GRP_ID = #{hqGrpCode}
OR EXISTS (
SELECT 1 FROM TF_F_CUST_GROUP_M b
WHERE b.CUST_ID = a.CUST_ID
AND GROUP_ID = #{hqGrpCode}
)
)
AND NOT EXISTS (
SELECT 1 FROM ZQZT_GRP_CONTRACT_OTHER_INFO c
WHERE c.INFO_VAL = a.USER_ID
AND CONTRACT_ID = #{contractId}
AND INFO_TAG = 'GRP_CONTRACT_USER_LIST'
AND IS_VALID = 1
)

    AND SVC_NUM in

